import { closeSync,constants,existsSync,fsyncSync,openSync,readFileSync,renameSync,statSync,unlinkSync,writeFileSync } from 'node:fs';
import path from 'node:path';
import { assertTranscriptReference,clone,pointLength,pointSlice,validateTranscript,type ResolvedReference,type SourceReference,type TranscriptSegment } from '../editor-core/model.js';
import type { AsrCapability,AsrContentState,AsrCorrection,AsrCorrectionSave,AsrCorrectionSaveResult,AsrDocument,AsrJob,AsrProgress,AsrProviderConfiguration,AsrResult,AsrSavedVersion } from '../shared/asr-contracts.js';
import type { EditorUnavailableSource } from '../shared/editor-contracts.js';
