function unavailableVersion(row:Row,revision:number,error:unknown,upstream=false):UnavailableVersion{
 let metadata:Partial<AsrResult>={};try{const parsed=JSON.parse(row.json);if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed))metadata=parsed;}catch{/* Never use unverified source text as a replacement. */}
 const code=upstream?'upstream-unavailable':sourceFailureCode(error),reason=code==='missing-file'?'该精确版本的转录文件缺失':code==='file-unavailable'?'该精确版本的转录文件暂不可读':code==='invalid-source'?'该精确版本的转录资料格式无效':code==='upstream-unavailable'?'该校对关联的原始转录文件缺失、不可读或摘要校验失败，尚不能核实其完整来源链':'该精确版本的转录文件或摘要校验失败';
 return{kind:'transcript',transcriptId:row.id,revision,segmentId:'segment-1',mediaId:String(row.media_id),...(typeof metadata.partId==='string'?{partId:metadata.partId}:{}),code,reason};
}
export class AsrSourceUnavailableError extends Error{
 constructor(readonly source:UnavailableVersion){super(`转录来源不可用：${source.transcriptId} / revision ${source.revision} / ${source.segmentId}；${source.reason}。原引用保留，请恢复该确切版本，不能用新结果替换旧引用。`);this.name='AsrSourceUnavailableError';}
}
/** Collect source health separately from the independently durable human draft/map. */
export function asrSourceInventory(db:Database.Database,contentId:number,workspaceId:string):{segments:TranscriptSegment[];unavailable:UnavailableVersion[]}{
 const inventory:{segments:TranscriptSegment[];unavailable:UnavailableVersion[]}={segments:[],unavailable:[]};
 if(!db.prepare("SELECT 1 FROM sqlite_master WHERE name='asr_results'").get())return inventory;
 const rows=db.prepare("SELECT * FROM asr_results WHERE content_id=? ORDER BY CASE WHEN json_valid(json) THEN json_extract(json,'$.mediaOrder') ELSE media_id END,chunk_order,created_at,rowid").all(contentId) as Row[];
 for(const row of rows){
  let raw:AsrResult|undefined,rawFailure:unknown;
  try{raw=verifyResult(db,row);inventory.segments.push({...clone(raw.segment),workspaceId});}catch(error){rawFailure=error;inventory.unavailable.push(unavailableVersion(row,1,error));}
  for(const saved of db.prepare('SELECT revision FROM asr_corrections WHERE result_id=? ORDER BY revision').all(row.id) as Row[]){
   try{const corrected=correction(db,row.id,saved.revision);if(!raw){inventory.unavailable.push(unavailableVersion(row,saved.revision,rawFailure,true));continue;}inventory.segments.push({...clone(corrected.segment),workspaceId});}
   catch(error){inventory.unavailable.push(unavailableVersion(row,saved.revision,error));}
  }
 }
 return inventory;
}
/** Compatibility helper returns healthy sources; callers needing warnings use the inventory. */
export function listAsrSegments(db:Database.Database,contentId:number,workspaceId:string):TranscriptSegment[]{return asrSourceInventory(db,contentId,workspaceId).segments;}
export function resolveAsrReference(db:Database.Database,workspaceId:string,ref:Extract<SourceReference,{kind:'transcript'}>):ResolvedReference|null{
 if(!db.prepare("SELECT 1 FROM sqlite_master WHERE name='asr_results'").get())return null;
 const row=db.prepare('SELECT * FROM asr_results WHERE id=?').get(ref.transcriptId) as Row|undefined;
 if(!row){if(ref.transcriptId.startsWith('asr-result-'))throw new AsrSourceUnavailableError({kind:'transcript',transcriptId:ref.transcriptId,revision:ref.revision,segmentId:ref.segmentId,code:'missing-file',reason:'该精确转录版本记录缺失'});return null;}
 const owner=db.prepare('SELECT content_id FROM editor_workspaces WHERE id=?').get(workspaceId) as Row|undefined;
 if(!owner||owner.content_id!==row.content_id)throw new Error('转录引用不属于本条收藏');
 let raw:AsrResult,segment:TranscriptSegment;
 try{raw=verifyResult(db,row);}catch(error){throw new AsrSourceUnavailableError({...unavailableVersion(row,ref.revision,error,ref.revision!==1),segmentId:ref.segmentId});}
 try{segment=ref.revision===1?raw.segment:correction(db,raw.resultId,ref.revision).segment;}catch(error){throw new AsrSourceUnavailableError({...unavailableVersion(row,ref.revision,error),segmentId:ref.segmentId});}
 if(ref.segmentId!==segment.segmentId)throw new Error('转录引用段落不符');
 const transcript=assertTranscriptReference(ref,segment),text=segment.runs.map(r=>r.text).join('');let selectedText=text;
 if(ref.range){const r=ref.range;if(r.end>pointLength(text))throw new Error('转录引用选区越界');selectedText=pointSlice(text,r.start,r.end);if(r.excerpt!==undefined&&r.excerpt!==selectedText||r.before!==undefined&&r.before!==pointSlice(text,Math.max(0,r.start-pointLength(r.before)),r.start)||r.after!==undefined&&r.after!==pointSlice(text,r.end,r.end+pointLength(r.after)))throw new Error('转录引用摘录或锚点不符');}
 return{kind:'transcript',text,selectedText,assets:clone(ref.assets??[]),version:String(ref.revision),targetId:segment.segmentId,transcript};
}
